\node[branchreason] at (4.5,-7.5) {\Tx{比較式と非負交点数から数値次元を同定。}{Identify numerical dimension through comparisons and nonnegative intersections.}\\\CiteSource{S}{(6.4)--(6.7), pp. 25--26}};
