\node[branchreason] at (4.5,-12.5) {\Tx{nef log abundant 随伴因子に適用。}{Apply semiampleness for nef log abundant adjoints.}\\\CiteSource{FG}{[FG] Thm. 4.2, p. 18}\\\CiteSource{S}{Sec. 6.3, p. 27}};
